using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;

namespace MyMcpServer;

[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _httpClient;

    // Constructor injection — the DI container provides HttpClient automatically
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool, Description("Gets the current weather for a given city.")]
    public async Task<string> GetWeather(
        [Description("City name, e.g. 'Seattle'")] string city)
    {
        var response = await _httpClient.GetAsync(
            $"/v1/weather?city={Uri.EscapeDataString(city)}");

        if (!response.IsSuccessStatusCode)
            return $"Error: API returned {response.StatusCode}";

        var result = await response.Content.ReadFromJsonAsync<WeatherResult>();
        return $"{city}: {result?.TempC}°C, {result?.Condition}";
    }

    [McpServerTool, Description("Gets a 3-day forecast for a city.")]
    public async Task<string> GetForecast(
        [Description("City name")] string city,
        [Description("Number of days (1-3)")] int days = 3)
    {
        var response = await _httpClient.GetAsync(
            $"/v1/forecast?city={Uri.EscapeDataString(city)}&days={days}");

        if (!response.IsSuccessStatusCode)
            return $"Error: API returned {response.StatusCode}";

        return await response.Content.ReadAsStringAsync();
    }
}

public record WeatherResult(double TempC, string Condition);

using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using MyMcpServer;

var builder = Host.CreateApplicationBuilder(args);

builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

// Register a typed HttpClient for WeatherTools
builder.Services.AddHttpClient<WeatherTools>(client =>
{
    client.BaseAddress = new Uri("https://api.example.com");
    client.DefaultRequestHeaders.Add("Accept", "application/json");
});

var app = builder.Build();
await app.RunAsync();

